                detayAciklama: 'Wíjẹ́ẹ̀tì àti ojú-ìwé "Āyah ti òní" nínú ìṣàfilọ́lẹ̀ ń fi āyah kan náà hàn. Ọ̀rọ̀ Lárúbáwá wá láti Tanzil Project, àwọn ìtumọ̀ sì wá láti QuranEnc, láìyí wọn padà.',
