                aciklama: 'ప్రతిరోజూ ఫజ్ర్‌లో మారే ఒక ఆయత్‌ను, దాని అనువాదాన్ని విడ్జెట్‌గా మీ హోమ్ స్క్రీన్‌కు, లాక్ స్క్రీన్‌కు జోడించండి.',
