                detayAciklama: 'Ang widget ug ang panid nga "Bersikulo sa adlaw" sa app nagpakita sa samang bersikulo. Ang Arabikong teksto gikan sa Tanzil Project ug ang mga hubad gikan sa QuranEnc, walay kausaban.',
                ctaEtiketi: 'Ablihi ang bersikulo sa adlaw',
