                aciklama: 'ߊߟߎ߫ ߦߋ߫ ߊߦߊ ߣߌ߫ ߊ߬ ߓߊߦߍߟߍߡߊ߲ߠߌ ߡߌ߲߬ ߓߍ߫ ߦߍߟߍߡߊ ߟߏ߲ ߏ߬ ߟߏ߲ ߖߍߡߎߙߍ߲ ߣߊ߬߸ ߏ߬ ߟߊ߫ ߊߟߎ߫ ߟߊ߫ Home Screen ߣߌ߫ Lock Screen ߞߊ߲ Widget ߦߋ߫.',
