                    'የትኛው የጊዜ ሰሌዳ ጥቅም ላይ እንደዋለ ለማየት በመነሻ ገጹ ላይ ያለውን የዘዴ ምልክት ይንኩ፤ አስርን እና እያንዳንዱን የሶላት ሰዓት ከመስጂድዎ ጋር እንዲዛመድ በደቂቃ ያስተካክሉ።',
