                    'ഏത് സമയപ്പട്ടികയാണ് ഉപയോഗിക്കുന്നതെന്ന് കാണാൻ ഹോം സ്ക്രീനിലെ രീതി ചിപ്പിൽ ടാപ്പ് ചെയ്യുക; നിങ്ങളുടെ പള്ളിക്കനുസരിച്ച് അസ്റും ഓരോ നമസ്കാര സമയവും മിനിറ്റ് തോറും ക്രമീകരിക്കാം.',
