                detayAciklama: 'Під’єднайте обліковий запис Google одним дотиком; застосунок бачить лише власну приховану папку на Drive, а не ваші файли. Дані шифруються вашим паролем, перш ніж залишити телефон; пароля не знаємо й ми, тож не забувайте його. Молитва синхронізується, щойно ви її позначите; також можна синхронізувати щогодини чи щодня, лише через Wi-Fi або лише під час заряджання. Коли ввімкнено енергозбереження, синхронізація чекає на заряджання. Молитви, позначені на двох пристроях, об’єднуються; жодна не видаляється.',
