                detayAciklama: 'Google ანგარიშს ერთი შეხებით დააკავშირებთ; აპი Drive-ში მხოლოდ საკუთარ დამალულ საქაღალდეს ხედავს და თქვენს ფაილებს არასოდეს. ტელეფონიდან გასვლამდე მონაცემები თქვენი პაროლით იშიფრება; პაროლი არც ჩვენ ვიცით, ამიტომ არ დაგავიწყდეთ. ლოცვა მონიშვნისთანავე სინქრონიზდება; შეგიძლიათ სინქრონიზაცია ყოველ საათში ან დღეში ერთხელაც, მხოლოდ Wi-Fi-ზე ან მხოლოდ დატენვისას. ბატარეის დაზოგვის ჩართვისას სინქრონიზაცია დატენვას ელოდება. ორ მოწყობილობაზე მონიშნული ლოცვები ერთიანდება; არცერთი არ იშლება.',
