                detayAciklama: '„Google“ paskyrą prijungsite vienu palietimu; programa „Google Drive“ mato tik savo paslėptą aplanką, o jūsų failų – niekada. Prieš paliekant telefoną duomenys užšifruojami jūsų slaptažodžiu; slaptažodžio nežinome ir mes, todėl jo nepamirškite. Malda sinchronizuojama vos ją pažymėjus; taip pat galite sinchronizuoti kas valandą ar kasdien, tik per „Wi-Fi“ arba tik kraunant. Kai įjungtas energijos taupymas, sinchronizavimas laukia įkrovimo. Dviejuose įrenginiuose pažymėtos maldos sujungiamos; nė viena neištrinama.',
