                aciklama: 'Zalimi ya yi jiŋa, yi dolibu mini Labi puhibu gbaŋ yi maŋ Google Drive ni ka laɣim li ni yi tilifoŋ shɛli bee tablet. Bɛ sɔɣiri yi lahabali ni paswɛdi shɛli yi ni piri.',
                detayAciklama: 'Laɣimmi ya yi Google akaunti ni dihibu yini; app maa nyari di maŋ faali din sɔɣi Drive ni koŋko, ka bi nyari yi faali nima. Bɛ sɔɣiri yi lahabali ni yi paswɛdi pɔi ka di yi tilifoŋ ni; ti mi bi mi paswɛdi maa, dinzuɣu di tam ya li. Jiŋli laɣindi yomyom yi yi dalim li; yi lahi ni tooi laɣim hawa kam bee dabsili kam, Wi-Fi zuɣu koŋko bee chaaji deebu ni koŋko. Baatri gubu yi yooya, laɣimbu guhiri chaaji deebu. Bɛ laɣindi jiŋa shɛŋa bɛ ni dalim kpatuɣa ayi zuɣu; bɛ bi yihiri shɛli.',
