                detayAciklama: 'Ikunekta su Google account nu sa isa a tap; su app na pedilay bu sa sarili a nakalimun a folder nin sa Drive, di sa manga file nu. Naka-encrypt su datos nu sa password nu sa di pan lumyu sa telepono; di nami bun katawan su password, na di nu kalipatan. Mag-sync su sambayang amayka tandaan nu; maka-sync kanu bun uman oras atawka uman gay, sa Wi-Fi bu atawka amayka pedcharge bu. Amayka naka-on su battery saver, pedtagad su sync taman sa pedcharge. Su manga sambayang a natandaan sa dua a device na pedtimuen; da makwa.',
