                    'ߘߏߜߏߟߌ ߞߊ߬ ߓߐ߫ ߝߊ߲߭ ߞߋߟߋ߲߫ ߣߊ߬ ߞߊ߬ ߛߋ߫ ߝߊ߲߭ ߕߐ߮ ߡߊ߬: ߊߟߎ߫ ߘߐߙߐ߲߫ ߘߋ߬ ߓߍ߫ ߕߊ߬ߡߌ߲߬ߞߊ߲ ߠߐ߲߫',
