                detayAciklama: 'መሣሪያዎቼ › ታብሌት ወይም ስልክ አክል፦ በአንዱ መሣሪያ ላይ ኮድ ያሳዩና በሌላው ላይ ይቃኙት፤ ሁለቱም ገጾች ማረጋገጫ ይጠይቃሉ። መተግበሪያው በሁለቱም ላይ ክፍት ሆኖ በአንድ Wi-Fi ላይ ሲሆኑ ሶላቱ ወዲያውኑ ያልፋል፤ ካልሆነ ሁለቱም አብረው በሚከፈቱበት በሚቀጥለው ጊዜ።',
