                detayAciklama: 'మొదటి జత సమయంలో ఫోన్, టీవీ ఒకదానినొకటి ఆమోదిస్తాయి: మీ ఫోన్‌లో టీవీ పేరు చూసి, టీవీలో రిమోట్‌తో "జోడించండి" నొక్కండి. ఆ తర్వాత అంతా ఎన్‌క్రిప్ట్ చేయబడి మీ ఇంటి Wi-Fiలోనే ఉంటుంది. టీవీలో మీ స్థితిని లెక్కించడం డిఫాల్ట్‌గా ఆఫ్‌లో ఉంటుంది; మీరు ఆన్ చేయకపోతే, టీవీ నమాజ్ సమయాలను మాత్రమే చూపిస్తుంది. రమదాన్‌లో ఇఫ్తార్, సహరీ కౌంట్‌డౌన్‌లు, శుక్రవారాల్లో జుమా కార్డు కూడా పెద్ద స్క్రీన్‌పై కనిపిస్తాయి.',
