                detayAciklama: 'రిమైండర్‌లు › నమాజ్ సమయం ప్రారంభమైనప్పుడు కింద, ఆన్ చేసిన ప్రతి నమాజ్‌కు సౌండ్ వరుస ఉంటుంది. మీ ఫోన్ సౌండ్‌లలో ఒకదాన్ని ఎంచుకోండి లేదా మీ సొంత ఫైల్‌ను జోడించండి. ఫైల్ మీ ఫోన్ నోటిఫికేషన్‌ల ఫోల్డర్‌కు కాపీ చేయబడుతుంది, కాబట్టి అసలు ఫైల్‌ను తొలగించినా సౌండ్ ప్లే అవుతూనే ఉంటుంది. నమాజ్ సంరక్షకుడి దశల్లో కూడా ఇదే ఎంపిక ఉంది.',
