                detayAciklama: 'Mu Ebijjukizo › Ng’ekiseera ky’esswala kituuse, buli sswala eteereddwako erina olunyiriri lw’eddoboozi. Londa limu ku maloboozi g’essimu yo oba gattako fayiro yo. Fayiro ekoppololwa mu kifo kya Notifications eky’essimu yo, n’olwekyo eddoboozi ligenda mu maaso okuvuga ne bw’osangula eyasooka. Ekisoboka kino kiri ne mu mitendera gy’Omukuumi w’Esswala.',
